"use client"

import * as React from "react"
import {
  GlimmProvider,
  useGlimm,
  type GlimmDefaults,
  type PaletteName,
} from "glimm/react"

type GlimmBandWidthProps = Omit<GlimmDefaults, "bandTight" | "palette"> & {
  className?: string
  initialBandTight?: number
  palette?: PaletteName
}

function EyeIcon() {
  return (
    <svg aria-hidden="true" fill="none" height="13" viewBox="0 0 24 24" width="13">
      <path clipRule="evenodd" d="M12.0015 4C15.8807 4.00003 19.6594 6.31907 22.1829 10.7475C22.6254 11.524 22.6254 12.476 22.1829 13.2526C19.6594 17.681 15.8806 20 12.0015 19.9999C8.12239 19.9999 4.34363 17.6809 1.82016 13.2524C1.37766 12.4759 1.37766 11.5239 1.82016 10.7474C4.34363 6.31896 8.1224 3.99997 12.0015 4ZM8.3765 12C8.3765 9.99797 9.99947 8.375 12.0015 8.375C14.0036 8.375 15.6265 9.99797 15.6265 12C15.6265 14.002 14.0036 15.625 12.0015 15.625C9.99947 15.625 8.3765 14.002 8.3765 12Z" fill="currentColor" fillRule="evenodd" />
    </svg>
  )
}

function ExpandIcon() {
  return (
    <svg aria-hidden="true" fill="none" height="18" viewBox="0 0 24 24" width="18">
      <path clipRule="evenodd" d="M13 3.75C13 3.33579 13.3358 3 13.75 3H20.25C20.6642 3 21 3.33579 21 3.75V10.25C21 10.6642 20.6642 11 20.25 11C19.8358 11 19.5 10.6642 19.5 10.25V5.56066L14.2803 10.7803C13.9874 11.0732 13.5126 11.0732 13.2197 10.7803C12.9268 10.4874 12.9268 10.0126 13.2197 9.71967L18.4393 4.5H13.75C13.3358 4.5 13 4.16421 13 3.75ZM3 13.75C3 13.3358 3.33579 13 3.75 13C4.16421 13 4.5 13.3358 4.5 13.75V18.4393L9.71967 13.2197C10.0126 12.9268 10.4874 12.9268 10.7803 13.2197C11.0732 13.5126 11.0732 13.9874 10.7803 14.2803L5.56066 19.5H10.25C10.6642 19.5 11 19.8358 11 20.25C11 20.6642 10.6642 21 10.25 21H3.75C3.33579 21 3 20.6642 3 20.25V13.75Z" fill="currentColor" fillRule="evenodd" />
    </svg>
  )
}

function BandWidthPanel({ initialBandTight, palette }: { initialBandTight: number; palette: PaletteName }) {
  const [bandTight, setBandTight] = React.useState(initialBandTight)
  const { sweep } = useGlimm()
  const preview = React.useCallback(
    () => sweep(() => undefined, { bandTight, palette }),
    [bandTight, palette, sweep],
  )
  const softness = 30 - ((bandTight - 5) / 45) * 20

  return (
    <>
      <div style={{ background: "#f7f7f7", borderRadius: "12px", boxShadow: "inset 0 0 0 0.5px rgba(0,0,0,0.04)", padding: "13px" }}>
        <div style={{ aspectRatio: "16 / 9", background: "#fff", borderRadius: "8px", boxShadow: "inset 0 0 0 0.5px rgba(0,0,0,0.06)", cursor: "ew-resize", overflow: "hidden", position: "relative", width: "100%" }}>
          <div aria-hidden="true" style={{ background: `linear-gradient(90deg, rgba(255,255,255,0.96) 0%, rgba(223,207,255,0.86) ${softness}%, rgba(112,117,220,0.92) 50%, rgba(89,206,225,0.88) ${100 - softness}%, rgba(255,255,255,0.96) 100%)`, filter: `blur(${Math.max(4, 13 - bandTight / 5)}px)`, inset: "-12px", position: "absolute", transition: "filter 120ms ease, background 120ms ease" }} />
          <div aria-hidden="true" style={{ background: "radial-gradient(ellipse 70% 78% at 50% 50%, rgba(255,255,255,0) 55%, rgba(255,255,255,0.7) 82%, #fff 100%)", inset: 0, pointerEvents: "none", position: "absolute" }} />
          <span style={{ color: "#9ca3af", fontFamily: "Inter, ui-sans-serif, system-ui, sans-serif", fontSize: "13px", fontVariantNumeric: "tabular-nums", fontWeight: 450, left: "10px", lineHeight: "18px", pointerEvents: "none", position: "absolute", top: "8px" }}>bandTight {bandTight}</span>
          <button aria-label="Preview on page" onClick={preview} type="button" style={{ alignItems: "center", background: "transparent", border: "none", color: "#bfbfbf", cursor: "pointer", display: "inline-flex", height: "30px", justifyContent: "center", padding: 0, position: "absolute", right: "10px", top: "10px", width: "30px", zIndex: 3 }}><ExpandIcon /></button>
          <input aria-label="bandTight" max="50" min="5" onChange={(event) => setBandTight(Number(event.currentTarget.value))} type="range" value={bandTight} style={{ cursor: "ew-resize", inset: 0, opacity: 0, position: "absolute", width: "100%", zIndex: 2 }} />
        </div>
        <div style={{ color: "#9ca3af", fontFamily: "Inter, ui-sans-serif, system-ui, sans-serif", fontSize: "13px", fontWeight: 450, letterSpacing: "-0.18px", lineHeight: "18px", marginTop: "8px" }}>Drag across the band to tune its width. Lower = wider, softer; higher = tighter, more concentrated.</div>
      </div>
      <div style={{ alignItems: "center", display: "flex", justifyContent: "flex-end", marginTop: "13px" }}>
        <button aria-label="Preview" onClick={preview} type="button" style={{ alignItems: "center", background: "#242529", border: "none", borderRadius: "999px", boxShadow: "0 0 0 0.75px #27272a inset, 0 0 0 1.25px rgba(255,255,255,0.30) inset, 0 8px 16px rgba(0,0,0,0.08), 0 16px 32px rgba(0,0,0,0.08)", color: "#fff", cursor: "pointer", display: "inline-flex", fontFamily: "Inter, ui-sans-serif, system-ui, sans-serif", fontSize: "12px", fontWeight: 450, gap: "6px", height: "28px", padding: "0 12px 0 10px" }}><EyeIcon />Preview</button>
      </div>
    </>
  )
}

function GlimmBandWidth({ className, initialBandTight = 14, palette = "prism", ...defaults }: GlimmBandWidthProps) {
  return (
    <GlimmProvider {...defaults}>
      <main className={className} style={{ alignItems: "center", background: "#fff", color: "#242529", display: "flex", justifyContent: "center", minHeight: "100vh", padding: "48px 32px", width: "100%" }}>
        <section style={{ maxWidth: "634px", width: "100%" }}><BandWidthPanel initialBandTight={initialBandTight} palette={palette} /></section>
      </main>
    </GlimmProvider>
  )
}

export { GlimmBandWidth }
export default GlimmBandWidth

